 {modal==='place'&&draft&&(()=>{const a=g.activities.find(a=>a.id===draft.activityId)!;const result=check(a,draft.date,draft.time,g,draft.placementId,draft.duration,draft.override);const existing=!draft.placementId&&!draft.duplicate&&g.placements.some(p=>p.activityId===a.id);return <Modal title={draft.placementId?'Uredi termin':'Pravi trenutek za doživetje'} close={close}><div className="placement-summary"><CategoryIcon category={a.category} size={28}/><div><h3>{a.title}</h3><p>{a.city} · {availabilityLabel(a)}</p></div></div><p className="muted">{a.windows.map(([s,e])=>`${time(s)}–${time(e)}`).join(' / ')} · {g.trip.timezone}</p><div className="form-grid"><label>Datum<input type="date" value={draft.date} onChange={e=>setDraft({...draft,date:e.target.value})}/></label><label>Začetek<input type="time" value={time(draft.time)} step="60" onChange={e=>setDraft({...draft,time:minutes(e.target.value)})}/></label><label>Trajanje (min)<input type="number" min="1" max="10080" value={draft.duration} onChange={e=>setDraft({...draft,duration:Number(e.target.value)})}/></label><label>Konec<strong className="end-time">{endInZone(draft.date,draft.time,draft.duration,g.trip.timezone)?.time||'—'}{(endInZone(draft.date,draft.time,draft.duration,g.trip.timezone)?.date||draft.date)>draft.date?' (naslednji dan)':''}</strong></label></div>{result.errors.map(e=><p className="validation error" key={e}>{e}</p>)}{existing&&<p className="validation error">Kartica že ima termin. Ponovitev lahko izrecno dodate iz zbirke kartic.</p>}{result.warnings.map(w=><p className="validation warning" key={w}>{w}</p>)}{result.valid&&!result.warnings.length&&<p className="validation success">Termin ustreza uvoženemu urniku.</p>}<label className="checkbox"><input type="checkbox" checked={draft.override} onChange={e=>setDraft({...draft,override:e.target.checked})}/>Izrecno dovoli prekrivanje in prezri čas za prevoz</label><div className="modal-actions"><button className="outline" onClick={close}>Prekliči</button><button className="primary" disabled={!result.valid||existing} onClick={()=>{const p:Placement={id:draft.placementId||uid(),activityId:a.id,date:draft.date,time:draft.time,duration:draft.duration,override:draft.override,startAt:instantISO(draft.date,draft.time,g.trip.timezone)||undefined,endAt:endInZone(draft.date,draft.time,draft.duration,g.trip.timezone)?.iso};const source=draft.duplicate?{kind:'repeat' as const,id:a.id}:sourceFor(g,a.id,draft.placementId);if(!applyMove(source,{kind:'board',placement:p,duplicate:draft.duplicate}))return;setDay(draft.date);setReveal(false);close();setNotice('Kartica ima svoje mesto. Naslednje doživetje že čaka.')}}><Check size={16}/>Potrdi termin</button></div>{draft.placementId&&<div className="return-actions"><button onClick={()=>returnCard(a.id,'deck',draft.placementId)}>Vrni na vrh kupčka</button><button onClick={()=>returnCard(a.id,'held',draft.placementId)}>Prestavi za pozneje</button></div>}</Modal>})()}
 {modal==='day-location'&&<Modal title={`Lokacija · ${dateLabel(locationDate,{day:'numeric',month:'long',year:'numeric'})}`} close={close}><p className="muted">Izberite ali vnesite lokacijo za ta dan. Sprememba datumov potovanja je ne bo izbrisala.</p><label>Lokacija dneva<input list="day-destinations" value={locationValue} placeholder="Lokacija ni določena." onChange={e=>setLocationValue(e.target.value)}/></label><datalist id="day-destinations">{[...new Set([...g.trip.segments.map(s=>s.city),...g.activities.map(a=>a.city),g.trip.destination])].filter(Boolean).map(city=><option key={city} value={city}/>)}</datalist><div className="modal-actions"><button className="outline" onClick={close}>Prekliči</button><button className="primary" onClick={()=>{const dayDestinations={...g.trip.dayDestinations};if(locationValue.trim())dayDestinations[locationDate]=locationValue.trim();else delete dayDestinations[locationDate];commit({...g,trip:{...g.trip,dayDestinations}});close()}}><Check size={16}/>Shrani lokacijo</button></div></Modal>}
 {modal==='pile'&&<Modal title={`Kupček ${inspectedPile+1} · ${g.undecided.piles[inspectedPile].length} kartic`} close={close}><p className="muted">Vrstni red od spodaj navzgor. Premaknete lahko samo vrhnjo kartico.</p><ol className="expanded-pile">{g.undecided.piles[inspectedPile].map((id,i)=>{const a=g.activities.find(a=>a.id===id)!;return <li key={id}><span>{i+1}</span><div><strong>{a.title}</strong><small>{a.city} · {a.duration} min{i===g.undecided.piles[inspectedPile].length-1?' · Vrhnja kartica':''}</small></div><button className="icon-btn" aria-label={`Podrobnosti: ${a.title}`} onClick={()=>openEdit(id)}><BookOpen size={16}/></button></li>})}</ol>{!g.undecided.piles[inspectedPile].length&&<p className="muted">Prazen kupček. Povlecite katerokoli vrhnjo kartico sem.</p>}</Modal>}
 {modal==='trip-picker'&&<Modal title="Moja potovanja" close={close}><div className="export-options">{savedTrips.map(h=><button key={h.present.trip.id} onClick={()=>{setHistory(h);setDay(savedBoardDate(h.present.trip));close()}}><Compass/><span><strong>{h.present.trip.name}</strong><small>{h.present.trip.start} – {h.present.trip.end} · {h.present.placements.length} terminov</small></span>{h.present.trip.id===g.trip.id?<Check size={17}/>:<ArrowRight size={17}/>}</button>)}</div><div className="modal-actions"><button className="outline" onClick={()=>setModal('settings')}>Uredi trenutno</button><button className="primary" onClick={()=>setModal('new-trip')}><Plus size={15}/>Novo prazno potovanje</button></div><button className="text-action" onClick={()=>{commit(demo());setDay('2027-03-25');close()}}>Naloži demo Japonska</button></Modal>}
